 */
scwin.img_Excel_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDSTF05908.xml", SCREN_PROCS_TP_CD_07);
        if (dts.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd, {fileName: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "상호명 변경내역", type: "8"});
        } else {
