/**
 * @method
 * @name chk_VALID_OBJ_1_onclick
 * @description chk_VALID_OBJ_1 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chk_VALID_OBJ_1_onclick = function() {
    try {
        if (chk_VALID_OBJ_1.checked === true) {
            if (rdo_ISUR_CD.getValue() === "1") {
                // 발행사
                cmb_ISUR_CD.ComboDataID = "dts_ElwInst_E1";
            } else if (rdo_ISUR_CD.getValue() === "2") {
                cmb_ISUR_CD.ComboDataID = "dts_ElwUly_E1";
            }
        } else {
            if (rdo_ISUR_CD.getValue() === "1") {
                // 발행사
                cmb_ISUR_CD.ComboDataID = "dts_ElwInst";
            } else if (rdo_ISUR_CD.getValue() === "2") {
                cmb_ISUR_CD.ComboDataID = "dts_ElwUly";
            }
        }
        cmb_ISUR_CD.setSelectedIndex(0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05908.chk_VALID_OBJ_1_onclick" });
    }
};

